INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Softwarearchitektur > Webservice Service Oriented Architecture (SOA)
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist eine Service-Oriented Architecture (SOA) immer auf Webservices wie SOAP oder REST beschränkt?', 2, '[{"text": "Nein", "correct": true, "because": "SOA kann auch andere Protokolle nutzen"}, {"text": "Ja", "correct": false, "because": "Nicht auf Webservices limitiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Services in einer SOA unabhängig voneinander entwickelt und bereitgestellt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Unabhängigkeit ist ein Kernprinzip der SOA"}, {"text": "Nein", "correct": false, "because": "Unabhängigkeit ist zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss eine SOA immer eine zentrale Steuerungseinheit besitzen?', 2, '[{"text": "Nein", "correct": true, "because": "Dezentrale Architekturen sind möglich"}, {"text": "Ja", "correct": false, "because": "Keine zwingende Anforderung"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Wiederverwendbarkeit von Services ein Hauptmerkmal der SOA?', 2, '[{"text": "Ja", "correct": true, "because": "Wiederverwendung ist ein Schlüsselvorteil"}, {"text": "Nein", "correct": false, "because": "Wiederverwendbarkeit ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine SOA ohne standardisierte Schnittstellen funktionieren?', 2, '[{"text": "Nein", "correct": true, "because": "Standardisierte Schnittstellen sind für Interoperabilität nötig"}, {"text": "Ja", "correct": false, "because": "Interoperabilität leidet ohne Standards"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal beschreibt eine SOA am besten?', 2, '[{"text": "Lose gekoppelte Services", "correct": true, "because": "Fördert Flexibilität und Wiederverwendung"}, {"text": "Zentrale Codebasis", "correct": false, "because": "Typisch für Monolithen"}, {"text": "Hohe Abhängigkeit", "correct": false, "because": "Widerspricht SOA"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Vorteil der SOA ist am bedeutendsten?', 3, '[{"text": "Interoperabilität", "correct": true, "because": "Ermöglicht Integration verschiedener Systeme"}, {"text": "Geringere Komplexität", "correct": false, "because": "Komplexität kann steigen"}, {"text": "Schnellere Entwicklung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologie wird in einer SOA häufig für Webservices verwendet?', 2, '[{"text": "SOAP", "correct": true, "because": "Standardprotokoll für SOA"}, {"text": "Direkte Datenbankzugriffe", "correct": false, "because": "Nicht typisch"}, {"text": "FTP", "correct": false, "because": "Weniger gebräuchlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Nachteil tritt bei der SOA am häufigsten auf?', 2, '[{"text": "Komplexität der Verwaltung", "correct": true, "because": "Viele Services erhöhen Aufwand"}, {"text": "Langsame Performance", "correct": false, "because": "Abhängig von Umsetzung"}, {"text": "Geringe Flexibilität", "correct": false, "because": "Eher Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip sollte bei der Planung einer SOA Priorität haben?', 2, '[{"text": "Service-Wiederverwendbarkeit", "correct": true, "because": "Maximiert Effizienz"}, {"text": "Maximale Kopplung", "correct": false, "because": "Lose Kopplung ist Ziel"}, {"text": "Einheitliche Technologie", "correct": false, "because": "Flexibilität ist zentral"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale kennzeichnen eine SOA?', 4, '[{"text": "Lose Kopplung", "correct": true, "because": "Reduziert Abhängigkeiten"}, {"text": "Wiederverwendbare Services", "correct": true, "because": "Kernprinzip"}, {"text": "Standardisierte Schnittstellen", "correct": true, "because": "Fördern Interoperabilität"}, {"text": "Monolithische Struktur", "correct": false, "because": "Gegenteil von SOA"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine SOA?', 3, '[{"text": "Flexibilität", "correct": true, "because": "Services unabhängig anpassbar"}, {"text": "Interoperabilität", "correct": true, "because": "Integration verschiedener Systeme"}, {"text": "Wiederverwendbarkeit", "correct": true, "because": "Services mehrfach nutzbar"}, {"text": "Geringere Entwicklungskosten", "correct": false, "because": "Kosten können steigen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien werden häufig in einer SOA eingesetzt?', 4, '[{"text": "SOAP", "correct": true, "because": "Standard für Webservices"}, {"text": "REST", "correct": true, "because": "Leichtgewichtig und flexibel"}, {"text": "WSDL", "correct": true, "because": "Definiert Service-Schnittstellen"}, {"text": "Direkte Speicherzugriffe", "correct": false, "because": "Nicht typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen gibt es bei der Implementierung einer SOA?', 3, '[{"text": "Service-Orchestrierung", "correct": true, "because": "Koordination komplex"}, {"text": "Performance-Overhead", "correct": true, "because": "Netzwerkkommunikation"}, {"text": "Governance", "correct": true, "because": "Verwaltung vieler Services"}, {"text": "Einfache Skalierung", "correct": false, "because": "Skalierung ist komplex"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien sollten bei der Planung einer SOA beachtet werden?', 3, '[{"text": "Service-Autonomie", "correct": true, "because": "Unabhängigkeit fördern"}, {"text": "Standardisierung", "correct": true, "because": "Interoperabilität sichern"}, {"text": "Abstraktion", "correct": true, "because": "Details verbergen"}, {"text": "Zentrale Datenbank", "correct": false, "because": "Dezentral ist besser"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) SOA fördert die Wiederverwendbarkeit von Services. b) Sie ist auf SOAP beschränkt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wiederverwendung ja, SOAP nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Services in einer SOA sind lose gekoppelt. b) Eine zentrale Steuerung ist immer erforderlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Lose Kopplung ja, zentral nicht nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) SOA ermöglicht Interoperabilität zwischen Systemen. b) Sie ist immer einfacher als eine monolithische Architektur.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Interoperabilität ja, Einfachheit nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) REST kann in einer SOA verwendet werden. b) SOA erfordert keine standardisierten Schnittstellen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "REST ja, Standards nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Service-Orchestrierung ist eine Herausforderung in der SOA. b) SOA ist für kleine Projekte ungeeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Orchestrierung ja, Eignung flexibel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

